// Scheme B IDs (L2 contract). Sidecars may attach a real OTEL trace_id later.
const crypto = require('crypto');
const raw = ($input.first() && $input.first().json) || {};
const nested = raw.body && typeof raw.body === 'object' ? raw.body : {};
const headers = raw.headers || {};
const incoming = (
  nested.correlation_id ||
  raw.correlation_id ||
  headers['x-correlation-id'] ||
  headers['X-Correlation-Id'] ||
  ''
).toString().trim();
let correlation_id = crypto.randomUUID();
if (/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(incoming)) {
  correlation_id = incoming.toLowerCase();
}
const trace_id = crypto.randomBytes(16).toString('hex');
const span_id = crypto.randomBytes(8).toString('hex');
const traceparent = `00-${trace_id}-${span_id}-01`;
const health_url =
  (typeof $env !== 'undefined' && $env.OBS_FACADE_HEALTH_URL) ||
  'http://doc_python_ai:8001/health';
const gate_mode =
  (typeof $env !== 'undefined' && $env.OBS_QUALITY_GATE_MODE) || 'shadow';
return [{
  json: {
    correlation_id,
    trace_id,
    traceparent,
    gate_mode,
    health_url,
    facade: 'obs-kit',
  },
}];

const prev = $('Build Scheme B IDs').item.json || {};
const res = $input.item.json || {};
const status = res.statusCode || res.status || null;
const body = res.body && typeof res.body === 'object' ? res.body : res;
const ok = status === 200 || body.status === 'ok' || body.status === 'healthy' || body.ok === true;
return {
  ok: Boolean(ok),
  facade: 'obs-kit',
  correlation_id: prev.correlation_id,
  trace_id: prev.trace_id,
  traceparent: prev.traceparent,
  gate_mode: prev.gate_mode || 'shadow',
  health_url: prev.health_url,
  health_status_code: status,
  health: body,
};

const prev = $('Build Scheme B IDs').item.json || {};
const item = $input.item.json || {};
const errorMessage =
  item.error?.message ||
  item.message ||
  item.error_message ||
  'Health request failed';
return {
  ok: false,
  facade: 'obs-kit',
  correlation_id: prev.correlation_id,
  trace_id: prev.trace_id,
  traceparent: prev.traceparent,
  gate_mode: prev.gate_mode || 'shadow',
  health_url: prev.health_url,
  error_message: String(errorMessage).slice(0, 500),
};
